"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5083],{6141(e){e.exports=JSON.parse('{"title":"\uc815\ub9d0 \ub2e4\ub978 \uc5b8\uc5b4\ub85c \ubc14\uafd4\uc57c \ud558\ub098\uc694?","date":"2024-11-01","coverUrl":null,"html":"<h2 data-notion-block-id=\\"f1b9a92e-377b-4e46-92cd-5807416760e5\\" id=\\"f1b9a92e-377b-4e46-92cd-5807416760e5\\">\uc815\ub9d0 \ub2e4\ub978 \uc5b8\uc5b4\ub85c \ubc14\uafd4\uc57c \ud558\ub098\uc694?</h2><a href=\\"https://nolanlawson.com/2024/10/20/why-im-skeptical-of-rewriting-javascript-tools-in-faster-languages/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nolanlawson.com/2024/10/20/why-im-skeptical-of-rewriting-javascript-tools-in-faster-languages/</a><p data-notion-block-id=\\"6a8d30bc-2fe8-4282-b2a3-e099f589a875\\"><b>\uc2ec\uc724\uc12d</b>: JS \ub3c4\uad6c\ub4e4\uc774 \ucd5c\uadfc \ub2e4\ub978 \uc5b8\uc5b4\ub85c \uc7ac\uc791\uc131\ud558\ub294 \uac83\uc774 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc <a href=\\"https://ones-to-watch.ethansup.net/news/post/dadb3439-b509-4f21-b8a3-4646fdd233af\\">JS\ub3c4 \ucda9\ubd84\ud788 \ube60\ub97c \uc218 \uc788\uace0</a>, \ub2e4\ub978 \uc5b8\uc5b4\ub85c \uc791\uc131\ub41c JS \ub3c4\uad6c\uc758 \uc624\ub958\uac00 \uace0\uce58\uae30 \uc5b4\ub835\ub2e4\ub294 \uac83\uc740 \uc5b4\ub5a4 \ub3c4\uad6c\ub97c \uc120\ud0dd\ud560\uc9c0 \uace0\ubbfc\ud574\uc57c \ud560 \ubd80\ubd84\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ube60\ub978 \uac83\uc740 \uc88b\uc9c0\ub9cc, \ub514\ubc84\uae45/\ud638\ud658\uc131\u2026 \uac19\uc740 \ub2e8\uc810\uc740 \uac10\uc218\ud574\uc57c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"59863789-0c23-481a-8539-756c78ce984d\\" id=\\"59863789-0c23-481a-8539-756c78ce984d\\">Vercel\uacfc \ub9c8\uc774\ud06c\ub85c\ud504\ub860\ud2b8\uc5d4\ub4dc</h2><a href=\\"https://vercel.com/blog/how-vercel-adopted-microfrontends\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/how-vercel-adopted-microfrontends</a><p data-notion-block-id=\\"8832b6bb-66e1-4a93-9c29-170c3375c24f\\"><b>\uc2ec\uc724\uc12d</b>: Vercel\uc5d0\uc11c \ubcf8 \ub9c8\uc774\ud06c\ub85c\ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \uc811\uadfc \ubc29\uc2dd, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud588\ub294\uc9c0\ub97c \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub9c8\uc774\ud06c\ub85c\ud504\ub860\ud2b8\uc5d4\ub4dc \uad00\ub828 \uac1c\ub150\uacfc \ucd5c\uc2e0 \uae30\uc220\uc744 \ud1b5\ud574 \ub2e8\uc810\uc744 \ubcf4\uc644\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"80e87956-671b-44f6-a930-7cda0f6394c3\\" id=\\"80e87956-671b-44f6-a930-7cda0f6394c3\\">\ucd94\uc0c1\ud654\uc640 \uac04\uc811\uc801\uc778 \ub808\uc774\uc5b4\uc758 \ucc28\uc774</h2><a href=\\"https://fhur.me/posts/2024/thats-not-an-abstraction\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fhur.me/posts/2024/thats-not-an-abstraction</a><p data-notion-block-id=\\"e64fa6c6-a2e9-4855-b00d-39e60bba3b1b\\">\ucd94\uc0c1\ud654\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \uc0dd\uac01\uc744 \ud3bc\uce5c \uae00\uc785\ub2c8\ub2e4. \uc88b\uc740 \ucd94\uc0c1\ud654\ub294 \ud6a8\uc728\uc801\uc774\ub77c\ub294 \uac83\uc740 \ub204\uad6c\ub098 \uc54c\uc9c0\ub9cc, \ucd94\uc0c1\ud654\ub77c\uace0 \uc0dd\uac01\ud588\ub294\ub370 \ub798\ud37c\uc77c \uc218\ub3c4 \uc788\uace0, \ucd94\uc0c1\ud654\uac00 \ubcf5\uc7a1\ud558\uac8c \ub418\uc11c \uc548\ud558\ub290\ub2c8\ub9cc \ubabb\ud574\uc9c0\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc5ec\ub7ec\uac00\uc9c0 \uae00(<a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#ec85017c-c8bc-46e1-abbe-e69801686efa\\">\ucd94\uc0c1\ud654\ub294 \uc801\uc808\ud558\uac8c</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/abdeee1c-f704-449c-9b9c-77f2d5f1714a#461afe37-5f65-4800-978a-8227e6534566\\">DRY\uac00 \uc798\ubabb\ub418\uc5b4\uac00\ub294 \ubc29\uc2dd</a>)\uc744 \uc0b4\ud3b4\ubcf4\uace0 \uc811\uadfc \ubc29\uc2dd\uc744 \uc0dd\uac01\ud574\ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"06dd4ccc-1aab-46ea-8739-9f3e6c12f0c2\\" id=\\"06dd4ccc-1aab-46ea-8739-9f3e6c12f0c2\\">\ucee8\ud14c\uc774\ub108\uc5d0 \ub531 \ub9de\uac8c \ud14d\uc2a4\ud2b8 \ud45c\uc2dc\ud558\uae30</h2><a href=\\"https://sentry.engineering/blog/perfectly-fitting-text-to-container-in-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sentry.engineering/blog/perfectly-fitting-text-to-container-in-react</a><p data-notion-block-id=\\"f9b7eb6f-551e-41fd-8157-f8721f1d7d26\\">DOM\uacfc \uad00\ub828\ub41c \uc815\ubcf4\ub97c React\uc5d0\uc11c \ubaa8\ub450 \uad00\ub9ac\ud558\ub294 \uc811\uadfc\ubc29\uc2dd\uacfc, \uc678\ubd80\uc5d0\uc11c \uc811\uadfc\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud558\uba70 \uc7a5\ub2e8\uc810\uacfc \uc8fc\uc758\ud574\uc57c \ud560 \uc810\uc744 \ubaa8\ub450 \uc18c\uac1c\ud569\ub2c8\ub2e4. React\uc5d0\uc11c DOM\uc5d0 \uc811\uadfc\ud558\ub294 \ubc29\uc2dd\uc744 \ubc30\uc6cc\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"7dcf4d5e-2dab-46ce-af93-ff9120e28471\\" id=\\"7dcf4d5e-2dab-46ce-af93-ff9120e28471\\"><code>useCallback</code>\uc5d0\uc11c \uc678\ubd80 \ucf5c\ubc31 \ub2e4\ub8e8\uae30</h2><a href=\\"https://www.taniarascia.com/keyboard-shortcut-hook-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.taniarascia.com/keyboard-shortcut-hook-react/</a><p data-notion-block-id=\\"7b64ae07-f594-4117-958a-3455491b5418\\">\ud0a4\ubcf4\ub4dc \ub2e8\ucd95\ud0a4\ub97c \ub2e4\ub8e8\ub294 \ud6c5\uc744 \ub9cc\ub4e4\uba74\uc11c <code>useCallback</code>\uc744 \uc0ac\uc6a9\ud558\uba74\uc11c \uc0dd\uae30\ub294 \ud074\ub85c\uc800 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ud2b8\ub9ad\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18e8b0de-6bd2-4c8e-b58e-f1d0d244ec2b\\" id=\\"18e8b0de-6bd2-4c8e-b58e-f1d0d244ec2b\\">RN New Architecture \ub300\ube44\ud558\uae30</h2><a href=\\"https://blog.swmansion.com/react-natives-new-architecture-the-tricky-parts-1-2-bb0c16950f2d\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/react-natives-new-architecture-the-tricky-parts-1-2-bb0c16950f2d</a><p data-notion-block-id=\\"987e1151-8cf8-48cb-8ace-129c03fac29b\\">React Native\uc5d0\uc11c 0.76\ubc84\uc804\uc744 \ucd9c\uc2dc\ud558\uba74\uc11c <a href=\\"https://reactnative.dev/blog/2024/10/23/the-new-architecture-is-here\\">New Architecture\uc774 \uae30\ubcf8 \uc635\uc158\uc73c\ub85c \ubcc0\uacbd</a>\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub85c \uc778\ud574 \ubc14\uafd4\uc57c \ud560 \uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 <a href=\\"https://blog.kraken.com/product/engineering/how-kraken-fixed-performance-issues-via-incremental-adoption-of-the-react-native-new-architecture\\">New Architecture\uc744 \uc801\uc6a9\ud55c \uacfc\uc815\uc744 \uc18c\uac1c</a>\ud55c \uae00\ub3c4 \uc788\uc73c\ub2c8 \uad00\uc2ec\uc788\uc73c\uba74 \ubcf4\uc138\uc694.</p><h2 data-notion-block-id=\\"e8e717b2-5009-4c95-b8f7-b9a3701d5333\\" id=\\"e8e717b2-5009-4c95-b8f7-b9a3701d5333\\">NextJS(App router)\uc758 \uce90\uc2dc \uc804\ub7b5</h2><a href=\\"https://www.yoseph.tech/posts/nextjs/server-side-state-management-in-nextjs-a-deep-dive-into-react-cache\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.yoseph.tech/posts/nextjs/server-side-state-management-in-nextjs-a-deep-dive-into-react-cache</a><p data-notion-block-id=\\"0e06d6cd-03d0-4fc7-ab2a-e28600c436eb\\">NextJS\uc5d0\uc11c \uc11c\ubc84\uce21 \uc0c1\ud0dc\ub97c \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uacfc, React 19\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 <code>cache</code>\ud568\uc218\ub97c \uc0ac\uc6a9\ud560 \ub54c \uc8fc\uc758\ud560 \uc810\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"132e548d-8a8e-8038-9147-c8306ff5389f\\" id=\\"132e548d-8a8e-8038-9147-c8306ff5389f\\">CSS \uad6c\ubb38 \ud45c\uc900\uc744 \uc5b4\ub5bb\uac8c \uc815\ud574\uc57c \ud558\ub294\uac00</h2><a href=\\"https://webkit.org/blog/16026/css-masonry-syntax/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webkit.org/blog/16026/css-masonry-syntax/</a><p data-notion-block-id=\\"132e548d-8a8e-80ef-be59-ce3fa2b23bec\\">\ub0b4\uc6a9\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/022fc2c2-88d3-4c20-9075-defdea8ae65c#9d0a352a-1d90-489e-9eb0-6852db3646b2\\">Grid Masonry\uc5d0 \ub300\ud55c \uc0dd\uac01</a>\uc5d0\uc11c \ub098\uc628 \uad6c\ubb38\uc5d0 \ub300\ud55c Webkit \uce21\uc758 \uc785\uc7a5\uc744 \uc815\ub9ac\ud574 \ub193\uc740 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc W3C \uc6cc\ud0b9 \uadf8\ub8f9\uc774 \uc5b8\uc5b4 \uad6c\ubb38\uc5d0 \ub300\ud574 \uc120\ud0dd\ud558\ub294 \uae30\uc900\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\uae30\uc5d0 \uc774\ub97c \uae30\ub2a5 \ub9cc\ub4dc\ub294\ub370\uc5d0 \uc7ac\uc0ac\uc6a9\uc131\uacfc \ucf54\ub4dc \uad6c\uc131\ud558\ub294 \ub370\uc5d0 \uc801\uc6a9\ud574\ubcfc \uc218 \uc788\uc744\ub4ef\ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"132e548d-8a8e-8038-9de8-ff9d789fe692\\" id=\\"132e548d-8a8e-8038-9de8-ff9d789fe692\\">\uc2e0 \uae30\ub2a5/\uae30\uc220 \uc18c\uac1c</h2><a href=\\"https://alfy.blog/2024/10/19/linking-directly-to-web-page-content.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alfy.blog/2024/10/19/linking-directly-to-web-page-content.html</a><a href=\\"https://nextjs.org/blog/next-15\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-15</a><p data-notion-block-id=\\"132e548d-8a8e-803d-b50a-f7554ec32861\\">\uccab\ubc88\uc9f8 \uae00\uc740 \uac80\uc0c9\ud55c \ub2e8\uc5b4\ub97c \uac15\uc870\ud558\ub294 \uae30\ub2a5(URL Text Fragments)\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc740 NextJS 15 \ubc84\uc804 \ucd9c\uc2dc\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc5c5\uadf8\ub808\uc774\ub4dc\ub97c \uc704\ud55c \uc790\ub3d9 \ucf54\ub4dc \ubcc0\ud658, \uce90\uc2f1 \uae30\ubcf8\uac12 / \ube44\ub3d9\uae30 \uc694\uccad API\uac00 \ub208\uc5d0 \ub744\ub124\uc694.</p>"}')}}]);